package main
import("bytes";"crypto/sha256";"encoding/hex";"encoding/json";"image/color";"image/png";"os";"path/filepath")
func main(){var output []map[string]any;for _,root:=range os.Args[1:]{for _,name:=range []string{"opengraph-image.png","twitter-image.png"}{p:=filepath.Join(root,"lambda-features",name);data,err:=os.ReadFile(p);if err!=nil{panic(err)};img,err:=png.Decode(bytes.NewReader(data));if err!=nil{panic(err)};bounds:=img.Bounds();sum:=sha256.New();row:=make([]byte,bounds.Dx()*4);for y:=bounds.Min.Y;y<bounds.Max.Y;y++{for x:=bounds.Min.X;x<bounds.Max.X;x++{c:=color.NRGBAModel.Convert(img.At(x,y)).(color.NRGBA);i:=(x-bounds.Min.X)*4;row[i],row[i+1],row[i+2],row[i+3]=c.R,c.G,c.B,c.A};sum.Write(row)};encoded:=sha256.Sum256(data);output=append(output,map[string]any{"path":p,"name":name,"width":bounds.Dx(),"height":bounds.Dy(),"encodedBytes":len(data),"encodedSHA256":hex.EncodeToString(encoded[:]),"decodedNRGBA8SHA256":hex.EncodeToString(sum.Sum(nil))})}};json.NewEncoder(os.Stdout).Encode(output)}
